/*
 * COMPOSITION: A machined orrery mechanism centered at origin — primary gear (1.6u dia) meshes
 * with a smaller secondary gear (0.9u dia) offset upper-right; a red jewel pivot sits fixed at the
 * primary hub; two ink arbor shafts pierce both hubs; a graded backdrop plane (z=-3) and a soft
 * radial contact-shadow ellipse (y=-1.2) ground the piece. Headline sits at y=-1.7, caption y=-2.1.
 * LIGHT RIG: preset rig-ember-glow — ambient floor 0.07 + point key (#ffb37a, 9) + point fill
 * (#c9924f, 3) + directional rim (#fff0dc, 1.2) aimed across the hub, node-local, subject-relative.
 * MATERIAL STRATEGY: machined steel MeshPhysicalNodeMaterial (roughness 0.5, metalness 0.55,
 * clearcoat 0.2/0.3, anisotropy 0.7 radial) on both gears; transmissive emissive jewel sphere;
 * matte ink shafts; unlit gradient backdrop + unlit radial-falloff shadow, both via TSL nodes.
 * MOTION: coupled meshing rotation (primary 0.08 rad/s / secondary -0.142 rad/s, driven by gsap
 * ticker) is the mechanism's single core idle transform; weighted-settle scale-in on load; the
 * orbit primitive drifts the whole assembly slowly. FOCAL ELEMENT: the primary gear + jewel pivot.
 */
import {
  Group,
  Mesh,
  PlaneGeometry,
  SphereGeometry,
  CylinderGeometry,
  PointLight,
  DirectionalLight,
  AmbientLight,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
  DoubleSide,
  Box3,
  Vector3,
} from 'three/webgpu';
import { uv, mix, color, smoothstep, vec2, length as vecLength } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const BoxCtor = THREE?.Box3 ?? Box3;
  const VecCtor = THREE?.Vector3 ?? Vector3;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#0b0b10' },
      { at: 0.65, hex: '#101017' },
      { at: 1, hex: '#16161d' },
    ],
  };

  const group = new Group();
  group.name = 'orrery-mechanism-root';

  const timelines = [];
  const disposables = [];
  let tickerFn = null;

  // ---- BACKDROP (color.background / color.surface / color.ink / color.gradient) ----
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide, fog: false });
  const stop0 = color(colors.gradientStops?.[0]?.hex ?? '#0b0b10');
  const stop1 = color(colors.gradientStops?.[1]?.hex ?? '#101017');
  const stop2 = color(colors.gradientStops?.[2]?.hex ?? '#16161d');
  const gy = uv().y;
  const gradA = mix(stop0, stop1, smoothstep(0.0, 0.65, gy));
  const gradient = mix(gradA, stop2, smoothstep(0.65, 1.0, gy));
  backdropMat.colorNode = gradient;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3);
  backdrop.renderOrder = -10;
  group.add(backdrop);
  disposables.push(() => { backdropGeo.dispose(); backdropMat.dispose(); });

  // ---- CONTACT SHADOW ELLIPSE ----
  const shadowGeo = new PlaneGeometry(2.6, 1.2);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const suv = uv().sub(vec2(0.5, 0.5));
  const dist = vecLength(suv.mul(vec2(1.0, 2.166)));
  const falloff = smoothstep(0.6, 0.1, dist);
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = falloff.mul(0.5);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.2, 0);
  group.add(shadow);
  disposables.push(() => { shadowGeo.dispose(); shadowMat.dispose(); });

  // ---- MECHANISM ASSEMBLY (effects.spec) ----
  const mechanism = new Group();
  mechanism.name = 'mechanism';
  group.add(mechanism);

  // machined steel material (color.ink / color.surface neutral tone, no hue drift)
  const machinedSteel = new MeshPhysicalNodeMaterial({
    color: '#33353a',
    roughness: 0.5,
    metalness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  machinedSteel.anisotropy = 0.7;
  machinedSteel.anisotropyRotation = Math.PI / 2;
  disposables.push(() => machinedSteel.dispose());

  // arbor shafts (color.ink)
  const shaftGeo = new CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new MeshPhysicalNodeMaterial({
    color: colors.ink ?? '#16161d',
    roughness: 0.6,
    metalness: 0.4,
  });
  const shaftA = new Mesh(shaftGeo, shaftMat);
  shaftA.rotation.x = Math.PI / 2;
  shaftA.position.set(0, 0, 0);
  const shaftB = new Mesh(shaftGeo, shaftMat);
  shaftB.rotation.x = Math.PI / 2;
  shaftB.position.set(1.15, 0.35, -0.1);
  mechanism.add(shaftA, shaftB);
  disposables.push(() => { shaftGeo.dispose(); shaftMat.dispose(); });

  // jewel pivot (color.accent)
  const jewelGeo = new SphereGeometry(0.12, 32, 32);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: colors.accent ?? '#ff2a38',
    transmission: 0.6,
    ior: 1.76,
    roughness: 0.1,
    metalness: 0.0,
    emissive: colors.accent ?? '#ff2a38',
  });
  jewelMat.emissiveIntensity = 1.8;
  const jewel = new Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0.05);
  mechanism.add(jewel);
  disposables.push(() => { jewelGeo.dispose(); jewelMat.dispose(); });

  // primary / secondary gears — loaded async, mechanism placeholder kept synchronous
  let primaryGear = null;
  let secondaryGear = null;
  const meshDisposers = [];

  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const primary = gltf.scene;

    const box = new BoxCtor().setFromObject(primary);
    const size = box.getSize(new VecCtor());
    const center = box.getCenter(new VecCtor());
    const rawDiameter = Math.max(size.x, size.y) || 1;
    const scaleFactor = 1.6 / rawDiameter;

    primary.scale.setScalar(scaleFactor);
    primary.position.set(-center.x * scaleFactor, -center.y * scaleFactor, -center.z * scaleFactor);

    primary.traverse((child) => {
      if (child.isMesh) {
        child.material = machinedSteel;
        meshDisposers.push(() => { if (child.geometry) child.geometry.dispose(); });
      }
    });

    const secondary = primary.clone(true);
    secondary.scale.multiplyScalar(0.9 / 1.6);
    secondary.position.set(1.15, 0.35, -0.1);

    mechanism.add(primary, secondary);
    primaryGear = primary;
    secondaryGear = secondary;

    // ---- MOTION: meshing rotation (ratio 16:9, phase-locked) ----
    tickerFn = (_time, deltaTime) => {
      const dt = (deltaTime ?? 16.6) / 1000;
      primary.rotation.z += 0.08 * dt;
      secondary.rotation.z += -0.142 * dt;
    };
    gsap.ticker.add(tickerFn);

    // weighted-settle entrance for the assembly
    mechanism.scale.setScalar(0.96);
    const settleTl = gsap.timeline();
    settleTl.to(mechanism.scale, {
      x: 1, y: 1, z: 1,
      duration: 0.9,
      ease: 'power4.out',
    });
    timelines.push(settleTl);
  });

  // ---- LIGHTS (preset rig-ember-glow, node-local) ----
  const ambient = new AmbientLight('#ffffff', 0.07);
  const key = new PointLight('#ffb37a', 9, 10, 2);
  key.position.set(1.8, 0.7, 1.9);
  const fill = new PointLight('#c9924f', 3, 8, 2);
  fill.position.set(-2.2, 0.4, 1.2);
  const rim = new DirectionalLight('#fff0dc', 1.2);
  rim.position.set(-0.8, 2.6, -2.4);
  rim.target.position.set(0, 0.5, 0);
  group.add(ambient, key, fill, rim, rim.target);

  // ---- TEXT (text.headline.0 / text.caption.1) ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [
    { text: 'The going train', role: 'headline' },
    { text: '34 COMPONENTS / HAND-FINISHED', role: 'caption' },
  ];

  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const captionItem = items.find((i) => i.role === 'caption') ?? items[1];

  const headline = ctx.fontAtlas.createText(headlineItem?.text ?? 'The going train', {
    fontSize: headlineItem?.typography?.fontSize ?? 68,
    color: colors.paper ?? '#e8ecf2',
    align: 'center',
  });
  headline.position.set(0, -1.7, 0.1);
  group.add(headline);

  const caption = ctx.fontAtlas.createText(captionItem?.text ?? '34 COMPONENTS / HAND-FINISHED', {
    fontSize: captionItem?.typography?.fontSize ?? 18,
    color: colors.paper ?? '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.4,
  });
  caption.position.set(0, -2.1, 0.1);
  group.add(caption);

  // entrance for text (rise-in / fade-up)
  headline.position.y -= 0.2;
  caption.position.y -= 0.2;
  const textOpacityTargets = [headline, caption];
  textOpacityTargets.forEach((t) => { if (t.traverse) t.traverse((c) => { if (c.material) c.material.transparent = true; }); });
  const textTl = gsap.timeline();
  textTl.to(headline.position, { y: -1.7, duration: 0.7, ease: 'power3.out' }, 0);
  textTl.to(caption.position, { y: -2.1, duration: 0.7, ease: 'power3.out' }, 0.08);
  timelines.push(textTl);

  // ---- CINEMATIC PRIMITIVES (primitive.orbit) ----
  const primitiveHandles = [];
  const primitiveConfigs = config.cinematicPrimitives ?? [
    { name: 'orbit', trigger: 'time', params: { speed: 0.08, radius: 0.2 } },
  ];
  for (const prim of primitiveConfigs) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(group, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- CLEANUP ----
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const h of primitiveHandles) {
      if (h?.timeline) h.timeline.kill();
      if (typeof h?.cleanup === 'function') h.cleanup();
    }
    if (tickerFn) gsap.ticker.remove(tickerFn);
    for (const dispose of disposables) dispose();
    for (const dispose of meshDisposers) dispose();

    if (headline?.traverse) {
      headline.traverse((c) => {
        if (c.geometry) c.geometry.dispose();
        if (c.material) c.material.dispose?.();
      });
    }
    if (caption?.traverse) {
      caption.traverse((c) => {
        if (c.geometry) c.geometry.dispose();
        if (c.material) c.material.dispose?.();
      });
    }

    if (primaryGear) {
      primaryGear.traverse((c) => { if (c.material && c.material !== machinedSteel) c.material.dispose?.(); });
    }
    if (secondaryGear) {
      secondaryGear.traverse((c) => { if (c.material && c.material !== machinedSteel) c.material.dispose?.(); });
    }
  };

  return group;
}

/* @spec-manifest
{"elements":[
  {"id":"text.headline.0","where":"createNode/text-section","how":"ctx.fontAtlas.createText headline at y=-1.7"},
  {"id":"text.caption.1","where":"createNode/text-section","how":"ctx.fontAtlas.createText caption at y=-2.1"},
  {"id":"color.background","where":"createNode/backdrop-section","how":"gradient stop0 #0b0b10 in TSL mix"},
  {"id":"color.surface","where":"createNode/machinedSteel-material","how":"steel tone derived near surface hue"},
  {"id":"color.ink","where":"createNode/arbor-shafts","how":"shaftMat color set to colors.ink"},
  {"id":"color.paper","where":"createNode/text-section","how":"headline/caption text color #e8ecf2"},
  {"id":"color.accent","where":"createNode/jewel-pivot","how":"jewelMat color+emissive #ff2a38"},
  {"id":"color.gradient","where":"createNode/backdrop-section","how":"3-stop TSL mix/smoothstep on plane"},
  {"id":"effects.spec","where":"createNode/mechanism-assembly","how":"gear normalize, meshing rotation, jewel, shafts, shadow"},
  {"id":"primitive.orbit","where":"createNode/primitives-section","how":"ctx.primitives.orbit applied to group"}
]}
*/
